const i = $input.first().json || {};
const pick = o => o && (o.reference || o.modele);
const src = pick(i.query) ? i.query : (pick(i.body) ? i.body : i);
const ref = String(src.reference || '').toUpperCase().replace(/[^A-Z0-9-]/g, '');
const modele = String(src.modele || '').toUpperCase().replace(/\s+/g, '').replace(/[^A-Z0-9()\/-]/g, '');
const mots_cles = String(src.mots_cles || '').slice(0, 200);
const role = String(src.role || 'technicien').toLowerCase();
const mode = (!ref && modele) ? 'modele' : 'ref';
return [{ json: { ref, modele, mots_cles, role, mode } }];

const acc = $('Identifiants').first().json || {};
const e = $('Entree').first().json;
if (!acc.identifiant || !acc.mot_de_passe || !acc.browserless_token) return [{ json: { ok: false, erreur: 'table hiparts_acces incomplete (identifiant, mot_de_passe, browserless_token)' } }];

const script = async ({ page, context }) => {
  const base = 'https://www.hi-parts.fr';
  const out = { ok: false, etapes: [] };
  try {
    page.setDefaultTimeout(30000);
    page.setDefaultNavigationTimeout(40000);
    await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36');
    await page.goto(base + '/Login.aspx?ReturnUrl=%2f', { waitUntil: 'networkidle2' });
    const login = await page.$('input[name$="TextBoxLOGIN"]');
    const pass = await page.$('input[name$="TextBoxPASSWORD"]');
    if (!login || !pass) { out.erreur = 'champs de connexion introuvables'; return { data: out, type: 'application/json' }; }
    await login.type(String(context.identifiant));
    await pass.type(String(context.mot_de_passe));
    const btn = await page.$('[name$="LinkValider"]');
    await Promise.all([page.waitForNavigation({ waitUntil: 'networkidle2' }), btn ? btn.click() : pass.press('Enter')]);
    if (/Login\.aspx/i.test(page.url())) { out.erreur = 'connexion refusee'; return { data: out, type: 'application/json' }; }
    out.etapes.push('connecte');

    const res = await page.evaluate(async (ctx) => {
      const norm = s => String(s || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
      const cle = s => norm(s).replace(/[^A-Z0-9]/g, '');
      const post = async (url, body) => {
        const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json; charset=utf-8', 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify(body) });
        try { return await r.json(); } catch (e) { return {}; }
      };
      const o = {};

      // 1. modele
      const target = cle(ctx.modele);
      const chercher = async kw => ((await post('/mvc/Search/SearchProducts', { pageSize: 25, pageNumber: 0, keyword: kw, idFam: 0 })).ResultList) || [];
      let prods = await chercher(ctx.modele);
      if (!prods.length && !ctx.modele.includes('-')) prods = await chercher(ctx.modele.replace(/^([A-Z]+)(\d)/, '$1-$2'));
      let g = prods.find(p => cle(p.GAMME_CODE) === target) || prods.find(p => cle(p.GAMME_LIB) === target);
      if (!g) g = prods.find(p => { const c = cle(p.GAMME_CODE); return c && (c.startsWith(target) || target.startsWith(c)); });
      if (!g) {
        if (!prods.length && ctx.modele.length > 5) prods = await chercher(ctx.modele.slice(0, -2));
        o.found = false;
        o.proches = prods.slice(0, 8).map(p => p.GAMME_CODE);
        return o;
      }
      o.found = true;
      o.modele = g.GAMME_CODE;
      o.famille = g.FAMILLE_LIB;

      // 2. vues eclatees
      const lh = await (await fetch('/ListSchema.aspx?IDGAM=' + g.GAMME_ID + '&IDRUB=1')).text();
      let ids = [...new Set([...lh.matchAll(/FicheSchema\.aspx\?IDSCG=(\d+)/g)].map(m => m[1]))];
      if (!ids.length) {
        const r = await fetch('/FicheProduit.aspx?IDFAM=' + g.FAMILLE_ID + '&IDGAM=' + g.GAMME_ID);
        const m = /IDSCG=(\d+)/.exec(r.url);
        const h = await r.text();
        ids = m ? [m[1]] : [...new Set([...h.matchAll(/FicheSchema\.aspx\?IDSCG=(\d+)/g)].map(x => x[1]))];
      }
      ids = ids.slice(0, 8);

      // 3. lignes de nomenclature
      const pages = await Promise.all(ids.map(async id => ({ id, h: await (await fetch('/FicheSchema.aspx?IDSCG=' + id)).text() })));
      const rows = [];
      const vues = [];
      for (const p of pages) {
        const d = new DOMParser().parseFromString(p.h, 'text/html');
        const vue = String(d.title || '').split('-->').pop().trim();
        if (vue && !vues.includes(vue)) vues.push(vue);
        for (const t of d.querySelectorAll('table[refarticle]')) {
          const cells = [...t.querySelectorAll('td')].map(c => c.textContent.replace(/\s+/g, ' ').trim());
          rows.push({ vue, rel: t.getAttribute('rel') || '', ref: String(t.getAttribute('refarticle') || '').toUpperCase(), des: cells[1] || '', nid: t.id });
        }
      }
      o.vues = vues;
      o.nb_lignes = rows.length;

      // 4. designations manquantes : lues sur l article ou sur sa reference de remplacement
      const sansDes = rows.filter(r => !r.des || cle(r.des) === cle(r.ref)).slice(0, 12);
      await Promise.all(sansDes.map(async r => {
        try {
          const l = ((await post('/mvc/Search/SearchItems', { pageSize: 10, pageNumber: 0, keyword: r.ref, idFam: 0 })).ResultList) || [];
          const a = l.find(x => String(x.ARTICLE_REF || '').toUpperCase() === r.ref);
          let des = a ? String(a.DESIGNATION || '') : '';
          if (!des || cle(des) === cle(r.ref)) {
            const subs = a ? String(a.ARTICLE_SUBSTITUT || '') + ' ' + String(a.ARTICLE_SUBSTITUTPARENT || '') : '';
            const toks = (subs.toUpperCase().match(/[A-Z0-9-]{5,}/g) || []).filter(t => t !== r.ref).reverse();
            for (const tk of toks) {
              const l2 = ((await post('/mvc/Search/SearchItems', { pageSize: 10, pageNumber: 0, keyword: tk, idFam: 0 })).ResultList) || [];
              const b = l2.find(x => String(x.ARTICLE_REF || '').toUpperCase() === tk);
              if (b && b.DESIGNATION && cle(b.DESIGNATION) !== cle(tk)) { des = String(b.DESIGNATION); break; }
            }
          }
          if (!des || cle(des) === cle(r.ref)) {
            const alt = l.find(x => String(x.ARTICLE_REF || '').toUpperCase() !== r.ref && x.DESIGNATION && cle(x.DESIGNATION) !== cle(x.ARTICLE_REF));
            if (alt) des = String(alt.DESIGNATION);
          }
          if (des && cle(des) !== cle(r.ref)) r.des = des;
        } catch (e) {}
      }));

      // 5. correspondance mots-cles
      const syn = [
        [/VENTIL/, ['FAN MOTOR', 'MOTEUR VENT', 'MOTOR FAN', 'MOTEUR VENTIL']],
        [/HELICE/, ['PROPELLER', 'HELICE', 'TURBINE']],
        [/CARTE|ELECTRONIQUE/, ['PWB', 'PCB', 'P.W.B', 'CARTE', 'BOARD', 'INVERTER']],
        [/COMPRESS/, ['COMPRESSOR', 'COMPRESSEUR']],
        [/SONDE|CAPTEUR/, ['THERMISTOR', 'SONDE', 'SENSOR']],
        [/4 VOIES|VANNE 4|INVERSION/, ['REVERSING', '4 VOIES', '4-WAY']],
        [/DETENDEUR/, ['EXPANSION', 'DETENDEUR']],
        [/CONDENSATEUR/, ['CAPACITOR', 'CONDENSATEUR']],
        [/TELECOMMANDE/, ['REMOTE', 'TELECOMMANDE', 'CONTROLLER']],
        [/POMPE/, ['PUMP', 'POMPE']],
        [/ECHANGEUR|BATTERIE/, ['EXCHANGER', 'CONDENSER', 'EVAPORATOR', 'ECHANGEUR', 'BATTERIE']],
        [/FILTRE/, ['FILTER', 'FILTRE', 'STRAINER']],
        [/VOLET/, ['LOUVER', 'VOLET', 'STEPPING']],
        [/PRESSOSTAT/, ['PRESSURE SWITCH', 'PRESSOSTAT']]
      ];
      const demande = norm(ctx.mots);
      const kws = new Set(demande.split(/[,;\/]+/).map(s => s.trim()).filter(s => s.length >= 3));
      for (const [re, l] of syn) if (re.test(demande)) l.forEach(k => kws.add(k));
      const scored = rows.map(r => {
        const d = norm(r.des);
        let s = 0;
        for (const k of kws) if (d.includes(k)) s += k.length;
        return { r, s };
      }).filter(x => x.s > 0).sort((a, b) => b.s - a.s);
      const vus = new Set();
      const cands = [];
      for (const x of scored) { const k = x.r.ref + '|' + x.r.vue; if (!vus.has(k)) { vus.add(k); cands.push(x.r); } if (cands.length >= 5) break; }

      if (!cands.length) {
        o.candidats = [];
        o.liste = rows.map(r => r.vue + ' | rep ' + r.rel + ' | ' + r.ref + ' | ' + r.des);
        return o;
      }

      // 6. stock, prix, remplacement des candidats
      await Promise.all(cands.map(async c => {
        try {
          const r = await fetch('/ajax/SpelogWeb.Libraries.Core.ajax.SpelogAjaxObjects,SpelogWeb.ashx?_method=GetNomenclature&_session=r', { method: 'POST', headers: { 'Content-Type': 'text/plain; charset=utf-8', 'X-Requested-With': 'XMLHttpRequest' }, body: 'idNomenclature=' + c.nid + '\r\ntypeRub=PR\r\nidIncident=0\r\nmultirepere=false' });
          const h = await r.text();
          const st = /ImageSTOCK"[^>]*title="([^"]*)"/.exec(h) || /title="([^"]*)"[^>]*ImageSTOCK/.exec(h);
          c.stock = st ? st[1] : '';
          const txt = h.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/\\r\\n/g, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');
          const rp = /remplacement\s*:\s*([A-Z0-9-]+)/i.exec(txt);
          c.remplacement = rp ? rp[1].toUpperCase() : '';
          const px = /Prix unitaire HT\s*:\s*([\d .,]+)/i.exec(txt);
          const v = px ? parseFloat(px[1].replace(/\s/g, '').replace(',', '.')) : NaN;
          c.prix = isNaN(v) ? null : v;
        } catch (e) { c.stock = ''; }
        delete c.nid;
      }));
      o.candidats = cands;
      return o;
    }, { modele: String(context.modele || ''), mots: String(context.mots || '') });

    Object.assign(out, res);
    out.ok = true;
    return { data: out, type: 'application/json' };
  } catch (e) {
    out.erreur = 'exception: ' + (e && e.message ? e.message : String(e));
    return { data: out, type: 'application/json' };
  }
};

const code = 'export default ' + script.toString() + ';\n';
return [{ json: { ok: true, token: acc.browserless_token, body: JSON.stringify({ code, context: { identifiant: acc.identifiant, mot_de_passe: acc.mot_de_passe, modele: e.modele, mots: e.mots_cles } }) } }];

const acc = $('Identifiants').first().json || {};
const e = $('Entree').first().json;
const code = "export default async ({ page, context }) => {
  const base = 'https://www.hi-parts.fr';
  const out = { ok: false, etapes: [] };
  const ref = String(context.ref || '').toUpperCase();
  try {
    page.setDefaultTimeout(30000);
    page.setDefaultNavigationTimeout(40000);
    await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36');
    await page.goto(base + '/Login.aspx?ReturnUrl=%2f', { waitUntil: 'networkidle2' });
    out.etapes.push('login page');
    const login = await page.$('input[name$="TextBoxLOGIN"]');
    const pass = await page.$('input[name$="TextBoxPASSWORD"]');
    if (!login || !pass) { out.erreur = 'champs de connexion introuvables'; return { data: out, type: 'application/json' }; }
    await login.type(String(context.identifiant));
    await pass.type(String(context.mot_de_passe));
    const btn = await page.$('[name$="LinkValider"], #ctl00_MainContent_TAB_LOGIN_LinkValider, input[type="submit"]');
    await Promise.all([
      page.waitForNavigation({ waitUntil: 'networkidle2' }),
      btn ? btn.click() : pass.press('Enter')
    ]);
    out.url_apres_login = page.url();
    if (/Login\.aspx/i.test(page.url())) {
      out.erreur = 'connexion refusee';
      out.extrait = (await page.evaluate(() => document.body.innerText.slice(0, 500)));
      return { data: out, type: 'application/json' };
    }
    out.etapes.push('connecte');
    if (!ref) { out.ok = true; return { data: out, type: 'application/json' }; }

    // 1. recherche de l article
    const search = await page.evaluate(async (ref) => {
      const r = await fetch('/mvc/Search/SearchItems', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json; charset=utf-8', 'X-Requested-With': 'XMLHttpRequest' },
        body: JSON.stringify({ pageSize: 25, pageNumber: 0, keyword: ref, idFam: 0 })
      });
      return { status: r.status, text: await r.text() };
    }, ref);
    out.etapes.push('search ' + search.status);
    let d = null;
    try { d = JSON.parse(search.text); } catch (e) {}
    if (!d || !Array.isArray(d.ResultList)) {
      out.erreur = 'reponse recherche illisible';
      out.extrait = search.text.slice(0, 800);
      return { data: out, type: 'application/json' };
    }
    const list = d.ResultList;
    const a = list.find(x => String(x.ARTICLE_REF || '').toUpperCase() === ref);
    if (!a) {
      out.ok = true; out.found = false; out.introuvable = true;
      out.suggestions = list.slice(0, 5).map(x => x.ARTICLE_REF + ' (' + (x.DESIGNATION || '') + ')');
      return { data: out, type: 'application/json' };
    }
    function refs(v) {
      const o = [];
      try { const j = JSON.parse(v || '[]'); for (const g of j) for (const x of (g || [])) o.push(String(x).toUpperCase()); } catch (e) {}
      return o;
    }
    const parent = refs(a.ARTICLE_SUBSTITUTPARENT);
    const sub = refs(a.ARTICLE_SUBSTITUT);
    const tarif = String(a.TARIFHT || '').replace(/&nbsp;|&euro;|€|\s/g, '').replace(',', '.');
    const prix = parseFloat(tarif);
    out.found = true;
    out.article_id = a.ARTICLE_ID;
    out.ref_article = String(a.ARTICLE_REF);
    out.designation = String(a.DESIGNATION || '');
    out.vendable = Number(a.ARTICLE_VENDABLE) === 1;
    out.prix_public = isNaN(prix) ? null : prix;
    out.chaine = parent.length ? parent : sub;
    if (!out.chaine.length) {
      const rep = list.find(x => String(x.ARTICLE_REF || '').toUpperCase() !== ref && refs(x.ARTICLE_SUBSTITUTPARENT).includes(ref));
      if (rep) out.chaine = refs(rep.ARTICLE_SUBSTITUTPARENT);
    }
    out.sub = sub;

    // 2. cas d utilisation (vue eclatee)
    const uses = await page.evaluate(async (id) => {
      const r = await fetch('/mvc/Search/GetUsesCasesItem', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json; charset=utf-8', 'X-Requested-With': 'XMLHttpRequest' },
        body: JSON.stringify({ id: id })
      });
      return { status: r.status, text: await r.text() };
    }, a.ARTICLE_ID);
    out.etapes.push('uses ' + uses.status);
    let l = [];
    try { l = JSON.parse(uses.text); } catch (e) { l = []; }
    if (!Array.isArray(l)) l = [];
    const u = l[0] || {};
    out.modeles = [];
    for (const x of l) { const n = String(x.GAMME_LIB || ''); if (n && !out.modeles.includes(n)) out.modeles.push(n); }
    out.modeles = out.modeles.slice(0, 6);
    out.modele = String(u.GAMME_LIB || '');
    out.repere = String(u.ARTSCHEMAGAMME_REP || '');
    const idscg = u.SCHEMAGAMME_ID ? String(u.SCHEMAGAMME_ID) : '';
    out.idscg = idscg;
    if (!idscg) { out.ok = true; return { data: out, type: 'application/json' }; }

    // 3. vue eclatee : trouver la ligne de nomenclature
    await page.goto(base + '/FicheSchema.aspx?IDSCG=' + idscg, { waitUntil: 'networkidle2' });
    out.etapes.push('schema');
    const wanted = [out.ref_article].concat(out.chaine, out.sub).map(x => String(x).toUpperCase());
    const ligne = await page.evaluate((wanted, repere) => {
      const rows = Array.from(document.querySelectorAll('table[refarticle]'));
      const all = rows.map(t => ({ id: t.getAttribute('id'), ref: String(t.getAttribute('refarticle') || '').toUpperCase(), rel: t.getAttribute('rel') || '' }));
      const l = all.find(x => x.rel === repere && wanted.includes(x.ref)) || all.find(x => wanted.includes(x.ref)) || null;
      return { l, nb: all.length, sample: all.slice(0, 3) };
    }, wanted, out.repere);
    out.nb_lignes = ligne.nb;
    out.sample_lignes = ligne.sample;
    if (!ligne.l) { out.ok = true; return { data: out, type: 'application/json' }; }
    out.nomenc_id = ligne.l.id;

    // 4. lire la disponibilite
    const nom = await page.evaluate(async (nid) => {
      const r = await fetch('/ajax/SpelogWeb.Libraries.Core.ajax.SpelogAjaxObjects,SpelogWeb.ashx?_method=GetNomenclature&_session=r', {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain; charset=utf-8', 'X-Requested-With': 'XMLHttpRequest' },
        body: 'idNomenclature=' + nid + '\r\ntypeRub=PR\r\nidIncident=0\r\nmultirepere=false'
      });
      return { status: r.status, text: await r.text() };
    }, ligne.l.id);
    out.etapes.push('nomenclature ' + nom.status);
    const h = nom.text;
    const t = /ImageSTOCK"[^>]*title="([^"]*)"/.exec(h) || /title="([^"]*)"[^>]*ImageSTOCK/.exec(h);
    out.stock = t ? t[1] : '';
    const p = /class="labelpuht">([^<]*)</i.exec(h);
    if (p) { const v = parseFloat(p[1].replace(/&nbsp;|&euro;|€|\s/g, '').replace(',', '.')); if (!isNaN(v)) out.prix_nomenclature = v; }
    const rs = /class="LabelRefSubstitution">\s*(?:<span[^>]*>)?\s*([A-Z0-9-]+)\s*</.exec(h) || /articleref="([A-Z0-9-]+)"/.exec(h);
    out.ref_remplacement = rs ? rs[1].toUpperCase() : '';
    out.ok = true;
    return { data: out, type: 'application/json' };
  } catch (e) {
    out.erreur = 'exception: ' + (e && e.message ? e.message : String(e));
    return { data: out, type: 'application/json' };
  }
};
";
if (!acc.identifiant || !acc.mot_de_passe || !acc.browserless_token) return [{ json: { ok: false, erreur: 'table hiparts_acces incomplete (identifiant, mot_de_passe, browserless_token)' } }];
return [{ json: { ok: true, token: acc.browserless_token, body: JSON.stringify({ code, context: { identifiant: acc.identifiant, mot_de_passe: acc.mot_de_passe, ref: e.ref } }) } }];

function js(n) { try { return $(n).first().json; } catch (e) { return {}; } }
const e = js('Entree');
const ref = e.ref;
const admin = e.role === 'admin';
const fmt = n => n.toFixed(2).replace('.', ',') + ' EUR';
if (!ref) return [{ json: { resultat: 'Aucune reference de piece fournie.' } }];
const p = js('Preparer script');
if (!p.ok) return [{ json: { resultat: 'Impossible de consulter hi-parts.fr pour le moment (' + p.erreur + ').' } }];
const r = $input.first().json || {};
let a = r;
if (typeof r.data === 'string') { try { a = JSON.parse(r.data); } catch (e2) { a = { erreur: 'reponse navigateur illisible: ' + String(r.data).slice(0, 200) }; } }
else if (r.data && typeof r.data === 'object') a = r.data;
if (a && a.data && typeof a.data === 'object' && !('ok' in a)) a = a.data;
if (!a.ok) return [{ json: { resultat: 'Impossible de consulter hi-parts.fr pour le moment (' + (a.erreur || 'erreur navigateur') + '). Verifier sur le site ou demander a Laurent.' } }];
if (!a.found) {
  const sug = (a.suggestions || []).length ? ' References proches : ' + a.suggestions.join(', ') + '.' : '';
  return [{ json: { resultat: 'Reference ' + ref + ' introuvable sur hi-parts.fr (catalogue Hitachi).' + sug } }];
}
const out = [];
out.push('Piece Hitachi ' + a.ref_article + (a.designation && a.designation !== a.ref_article ? ' : ' + a.designation : ''));
const ch = a.chaine || [];
let remp = a.ref_remplacement && a.ref_remplacement !== a.ref_article ? a.ref_remplacement : '';
const derniere = ch.length ? ch[ch.length - 1] : '';
if (!remp && derniere && derniere !== a.ref_article) remp = derniere;
if (remp) out.push('Attention : cette reference est remplacee par ' + remp + '. Disponibilite et prix ci-dessous concernent la nouvelle reference.');
else if (ch.length > 1) out.push('Remplace l ancienne reference ' + ch.slice(0, -1).join(', ') + '.');
if (!a.vendable && !remp) out.push('Article indique non vendable sur le site.');
const pp = (a.prix_nomenclature != null) ? a.prix_nomenclature : (a.prix_public != null ? a.prix_public : null);
const st = String(a.stock || '');
let v;
if (/seuil minimal/i.test(st)) v = 'disponible, stock faible';
else if (/en stock/i.test(st)) v = 'disponible';
else if (/aucun stock/i.test(st) && pp != null) v = 'rupture de stock, piece toujours vendue : demander le delai de reappro';
else if (/aucun stock/i.test(st) && !remp) v = 'ni stock ni prix ni remplacement : piece tres probablement en fin de vie, prevoir un chiffrage de remplacement de la machine';
else if (/aucun stock/i.test(st)) v = 'ni stock ni prix, remplacement annonce : a confirmer avec Hitachi';
else v = 'disponibilite non lue, verifier sur hi-parts.fr';
out.push('Verdict : ' + v + (st ? ' (' + st + ')' : '') + '.');
if (pp != null) {
  out.push('Prix indicatif client : ' + fmt(Math.round(pp * 115) / 100) + ' HT, hors pose');
  if (admin) out.push('Prix public Hitachi (a afficher a Laurent) : ' + fmt(pp) + ' HT');
}
if (a.modele) out.push('Utilisee sur : ' + (a.modeles || [a.modele]).join(', ') + (a.repere ? ' (repere ' + a.repere + ' sur ' + a.modele + ')' : ''));
out.push('Source : hi-parts.fr');
return [{ json: { resultat: out.join('\n') } }];

function js(n) { try { return $(n).first().json; } catch (e) { return {}; } }
const e = js('Entree');
const admin = e.role === 'admin';
const fmt = n => n.toFixed(2).replace('.', ',') + ' EUR';
const p = js('Preparer modele');
